package com.cph.alpharoute.data.backup;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * A whole database, read out of a backup file.
 *
 * <p>Plain values rather than Room entities, and that is the point: this is what a <i>file</i> said, before
 * anything has been checked or written. Treating parsed file contents as entities would invite code to
 * treat them as data the app already trusts.
 *
 * <p><b>Stores are referenced by code, not by row id.</b> The ids are auto-generated by SQLite, so a
 * backup's ids mean nothing in the database it is restored into - store 7 there is not store 7 here.
 * {@code storeCode} is the app's own stable identity for a store, which is why the completion records in
 * this file point at codes.
 *
 * <p>Pure Java.
 */
public final class BackupContents {

    /** One store, as a file described it. */
    public static final class BackupStore {
        public final String routeNumber;
        public final String storeCode;
        public final String storeName;
        public final String area;
        public final double latitude;
        public final double longitude;
        public final String status;
        public final long createdAt;
        public final long updatedAt;
        @Nullable
        public final Long completedAt;

        public BackupStore(@Nullable String routeNumber,
                           @Nullable String storeCode,
                           @Nullable String storeName,
                           @Nullable String area,
                           double latitude,
                           double longitude,
                           @Nullable String status,
                           long createdAt,
                           long updatedAt,
                           @Nullable Long completedAt) {
            this.routeNumber = routeNumber == null ? "" : routeNumber;
            this.storeCode = storeCode == null ? "" : storeCode;
            this.storeName = storeName == null ? "" : storeName;
            this.area = area == null ? "" : area;
            this.latitude = latitude;
            this.longitude = longitude;
            this.status = status == null ? "" : status;
            this.createdAt = createdAt;
            this.updatedAt = updatedAt;
            this.completedAt = completedAt;
        }
    }

    /** One completion, as a file described it. */
    public static final class BackupCompletion {
        public final String storeCode;
        public final long completionTimestamp;
        public final String completionDateKey;
        public final int dailySequence;
        public final int roundNumber;

        public BackupCompletion(@Nullable String storeCode,
                                long completionTimestamp,
                                @Nullable String completionDateKey,
                                int dailySequence,
                                int roundNumber) {
            this.storeCode = storeCode == null ? "" : storeCode;
            this.completionTimestamp = completionTimestamp;
            this.completionDateKey = completionDateKey == null ? "" : completionDateKey;
            this.dailySequence = dailySequence;
            this.roundNumber = Math.max(1, roundNumber);
        }
    }

    /** The settings half of a backup. */
    public static final class BackupSettings {
        @Nullable
        public final Double homeLatitude;
        @Nullable
        public final Double homeLongitude;
        public final boolean homeSet;
        public final int arrivalRadius;
        public final int currentRound;

        public BackupSettings(@Nullable Double homeLatitude,
                              @Nullable Double homeLongitude,
                              boolean homeSet,
                              int arrivalRadius,
                              int currentRound) {
            this.homeLatitude = homeLatitude;
            this.homeLongitude = homeLongitude;
            this.homeSet = homeSet;
            this.arrivalRadius = arrivalRadius;
            this.currentRound = Math.max(1, currentRound);
        }
    }

    public final int formatVersion;
    public final long exportedAt;
    public final BackupSettings settings;
    public final List<BackupStore> stores;
    public final List<BackupCompletion> completions;

    public BackupContents(int formatVersion,
                          long exportedAt,
                          @Nullable BackupSettings settings,
                          @Nullable List<BackupStore> stores,
                          @Nullable List<BackupCompletion> completions) {
        this.formatVersion = formatVersion;
        this.exportedAt = exportedAt;
        this.settings = settings;
        this.stores = stores == null
                ? Collections.emptyList()
                : Collections.unmodifiableList(new ArrayList<>(stores));
        this.completions = completions == null
                ? Collections.emptyList()
                : Collections.unmodifiableList(new ArrayList<>(completions));
    }

    public int storeCount() {
        return stores.size();
    }

    public int completionCount() {
        return completions.size();
    }
}
